using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Diagnostics;using System.Threading;using System.Windows.Forms;using Gunt.ControlCenter.Models;
namespace Gunt.ControlCenter.Services {
 public sealed partial class DesktopService {
  public string LivelyDataOverride;string LivelyData{get{return LivelyDataOverride??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Lively Wallpaper");}}
  public string WallpaperLayoutFile{get{return Path.Combine(LivelyData,"WallpaperLayout.json");}}
  public string CurrentWallpaperTitle(){try{return String.Join(", ",Assignments().Select(x=>{string file=Path.Combine(S(x,"LivelyInfoPath"),"LivelyInfo.json");return File.Exists(file)?S(Json.Deserialize<Dictionary<string,object>>(GuntConfiguration.ReadShared(file)),"Title","설치 배경"):"배치 확인 필요";}));}catch{return "배경 정보 확인 필요";}}
  Dictionary<string,object>[] Assignments(){string p=Path.Combine(LivelyData,"WallpaperLayout.json");for(int retry=0;;retry++){try{return File.Exists(p)?(Json.Deserialize<Dictionary<string,object>[]>(GuntConfiguration.ReadShared(p))??new Dictionary<string,object>[0]):new Dictionary<string,object>[0];}catch{if(retry>=4)throw;Thread.Sleep(40);}}}
  public WallpaperEntry[] Wallpapers(){var settingsPath=Path.Combine(LivelyData,"Settings.json");if(!File.Exists(settingsPath))return new WallpaperEntry[0];var settings=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(settingsPath));string library=S(settings,"WallpaperDir",Path.Combine(LivelyData,"Library"));var roots=new[]{Path.Combine(library,"wallpapers"),Path.Combine(library,"SaveData","wptmp")};var favorites=Optional("wallpaper-gallery");var favoriteList=favorites.ContainsKey("favorites")?((IEnumerable)favorites["favorites"]).Cast<object>().Select(x=>Convert.ToString(x)).ToArray():new string[0];var assigned=Assignments();var result=new List<WallpaperEntry>();
   foreach(var folder in roots.Where(Directory.Exists))foreach(var dir in Directory.GetDirectories(folder)){string file=Path.Combine(dir,"LivelyInfo.json");if(!File.Exists(file))continue;try{var info=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(file));string thumb=S(info,"Thumbnail"),thumbPath=String.IsNullOrEmpty(thumb)?null:Path.GetFullPath(Path.Combine(dir,thumb));if(thumbPath!=null&&!thumbPath.StartsWith(dir+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))thumbPath=null;var screens=assigned.Where(x=>String.Equals(S(x,"LivelyInfoPath"),dir,StringComparison.OrdinalIgnoreCase)).Select(x=>S(x["LivelyScreen"] as Dictionary<string,object>,"DisplayName",S(x["LivelyScreen"] as Dictionary<string,object>,"DeviceName")));string media=S(info,"FileName"),ext=Path.GetExtension(media).ToLowerInvariant();string type=new[]{".mp4",".webm",".mkv",".mov"}.Contains(ext)?"영상":new[]{".html",".htm"}.Contains(ext)?"HTML / WebGL":"Lively 유형 "+S(info,"Type");result.Add(new WallpaperEntry{Path=dir,Title=S(info,"Title",Path.GetFileName(dir)),Thumbnail=thumbPath,Type=type,Favorite=favoriteList.Contains(dir,StringComparer.OrdinalIgnoreCase),Assigned=String.Join(", ",screens),Customizable=File.Exists(Path.Combine(dir,"LivelyProperties.json"))});}catch{}}
   return result.OrderByDescending(x=>x.Favorite).ThenBy(x=>x.Title).ToArray();}
  public void FavoriteWallpaper(string path){if(!Wallpapers().Any(x=>String.Equals(x.Path,path,StringComparison.OrdinalIgnoreCase)))throw new ArgumentException("설치된 배경 패키지가 아닙니다.");var data=Optional("wallpaper-gallery");var favorites=data.ContainsKey("favorites")?((IEnumerable)data["favorites"]).Cast<object>().Select(x=>Convert.ToString(x)).ToList():new List<string>();if(favorites.Contains(path))favorites.Remove(path);else favorites.Add(path);data["schemaVersion"]=1;data["favorites"]=favorites;GuntConfiguration.Save(Root,"wallpaper-gallery",data);}
  public DisplayEntry[] Displays(){return Screen.AllScreens.Select(x=>new DisplayEntry{Id=GuntLayout.MonitorId(x),Device=x.DeviceName,Index=Int32.Parse(System.Text.RegularExpressions.Regex.Match(x.DeviceName,@"\d+$").Value),Label=(x.Primary?"주 화면 · ":"")+"화면 "+Int32.Parse(System.Text.RegularExpressions.Regex.Match(x.DeviceName,@"\d+$").Value)+" · "+x.Bounds.Width+"×"+x.Bounds.Height+" · "+GuntLayout.Scale(x)*100+"%"}).ToArray();}
  public string WallpaperAssignments(){var wallpapers=Wallpapers();var assignments=Assignments();return String.Join("\n",Displays().Select(display=>{var match=assignments.FirstOrDefault(x=>S(x["LivelyScreen"] as Dictionary<string,object>,"DeviceId")==display.Id);var wp=match==null?null:wallpapers.FirstOrDefault(x=>String.Equals(x.Path,S(match,"LivelyInfoPath"),StringComparison.OrdinalIgnoreCase));return display.Label+": "+(wp==null?"라이브 배경 없음":wp.Title);}))+"\n재생 정책: "+(B(State("wallpaper-playback"),"ManualPaused")?"마지막 GUNT 요청은 수동 정지":"자동 정책 · 실제 재생은 Lively의 가림·전원 설정에 따름");}

  void Lively(string args){string exe=S(Optional("wallpaper"),"enginePath",Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","Lively Wallpaper","Lively.exe"));if(!File.Exists(exe))throw new FileNotFoundException("Lively 실행 경로를 찾지 못했습니다.");if(LaunchOverride!=null){LaunchOverride(new ProcessStartInfo(exe,args));return;}using(var p=Process.Start(new ProcessStartInfo(exe,args){UseShellExecute=false,CreateNoWindow=true})){if(!p.WaitForExit(12000))throw new TimeoutException("Lively 응답을 확인할 수 없습니다. 강제 종료하지 않았습니다.");if(p.ExitCode!=0)throw new IOException("Lively 요청 실패 코드 "+p.ExitCode);}}
  public string ApplyWallpaper(string path,string displayId,bool all){if(!Wallpapers().Any(x=>String.Equals(x.Path,path,StringComparison.OrdinalIgnoreCase)))throw new ArgumentException("다시 검색한 설치 패키지만 적용할 수 있습니다.");var screens=Displays().Where(x=>all||x.Id==displayId).ToArray();if(screens.Length==0)throw new ArgumentException("선택 화면이 연결되어 있는지 확인하세요.");var previous=Assignments();GuntConfiguration.Atomic(Root,Path.Combine(Root,"backups","wallpaper-assignment",DateTime.Now.ToString("yyyyMMddHHmmssfff")+".json"),Json.Serialize(previous),false);
   var affected=new List<DisplayEntry>();try{foreach(var screen in screens){affected.Add(screen);Lively("setwp --file "+Quote(path)+" --monitor "+screen.Index);}for(int i=0;i<40;i++){var current=Assignments();if(screens.All(screen=>current.Any(x=>S(x["LivelyScreen"] as Dictionary<string,object>,"DeviceId")==screen.Id&&String.Equals(S(x,"LivelyInfoPath"),path,StringComparison.OrdinalIgnoreCase))))return "Lively 배경 배치에서 선택 패키지와 대상 화면 "+screens.Length+"개를 확인했습니다.";Thread.Sleep(200);}throw new IOException("명령은 전달됐지만 실제 배경 배치가 일치하지 않습니다.");}catch(Exception original){var errors=new List<string>();foreach(var screen in affected){var prior=previous.FirstOrDefault(x=>S(x["LivelyScreen"] as Dictionary<string,object>,"DeviceId")==screen.Id);try{if(prior!=null)Lively("setwp --file "+Quote(S(prior,"LivelyInfoPath"))+" --monitor "+screen.Index);else Lively("closewp --monitor "+screen.Index);}catch(Exception e){errors.Add(e.Message);}}throw new IOException(original.Message+"\n이전 배치 복구 요청: "+(errors.Count==0?"전달 완료·실제 화면 재확인 필요":String.Join("; ",errors)));}}
  public Dictionary<string,object> SensorSnapshot(){return new GuntHwinfoTelemetry(Root).Read();}
 }
}
